<script setup lang="ts">

import {can} from './session'
import {ref,reactive,onMounted,watch} from 'vue'
import {api,session} from './session'
import {ElMessage} from 'element-plus'
import {withDefaults} from './customsData'
import CustomsFields from './CustomsFields.vue'
import {useTableWidths} from './tableWidths'
const props=defineProps<{kind:'declaration'|'clearance'}>(),widths=useTableWidths('ProductCustomsPanel'),rows=ref<any[]>([]),q=ref(''),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),editing=ref<any>(),form=reactive<any>({})
async function load(){busy.value=true;try{const d=await api('/products?'+new URLSearchParams({q:q.value,page:String(page.value)}));rows.value=d.rows;total.value=d.total;error.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function edit(row:any){try{const p=await api('/products/'+row.id);editing.value=p;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,withDefaults(p[props.kind]));for(const k of ['unit_price','tax_rate'])form[k]=form[k]==null?null:Number(form[k])}catch(e){ElMessage.error((e as Error).message)}}
async function save(){busy.value=true;try{await api(`/product-data/${editing.value.id}/${props.kind}`,{revision:editing.value.revision,detail:form});editing.value=null;await load();ElMessage.success('资料已保存')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
watch(()=>props.kind,()=>{page.value=1;editing.value=null;load()});onMounted(load)
</script>
<template><section><div class="customs-tools"><el-input v-model="q" placeholder="搜索标品编码 / 品名" clearable style="width:260px" @keyup.enter="page=1;load()"/><el-button type="primary" @click="page=1;load()">查询</el-button><el-button @click="q='';page=1;load()">重置</el-button><el-button @click="load">刷新列表</el-button><TableReset :table-key="'ProductCustomsPanel/'+kind"/></div><el-alert v-if="error" :title="error" type="error"/><template v-if="true"><el-table    :data="rows" v-loading="busy" border :data-width-key="'ProductCustomsPanel/'+kind" @header-dragend="(w:number,_:number,c:any)=>widths.resize(kind,w,c)"><el-table-column  :width="widths.width(kind,'product',280)" label="标品编码 / 品名" column-key="product" ><template #default="{row}"><b>{{row.code}}</b><div>{{row.name}}</div></template></el-table-column><el-table-column  :width="widths.width(kind,key,180)" v-for="(label,key) in {name_cn:'中文名称',name_en:'英文名称',hs_code:'HSCODE',model:'型号',origin:'原产地'}" :key="key" :label="label" :column-key="key" ><template #default="{row}">{{row[kind]?.[key]||'—'}}</template></el-table-column><el-table-column  :width="widths.width(kind,'price',150)" label="单价 / 币种" column-key="price" ><template #default="{row}">{{row[kind]?.unit_price??'—'}} {{row[kind]?.currency||''}}</template></el-table-column><el-table-column :column-key="'column-4'" :width="widths.width(kind,'column-4','110')" v-if="kind==='clearance'" label="税率" ><template #default="{row}">{{row[kind]?.tax_rate==null?'—':row[kind].tax_rate+'%'}}</template></el-table-column><el-table-column :column-key="'column-5'" :width="widths.width(kind,'column-5','90')" label="操作" fixed="right" ><template #default="{row}"><el-button link type="primary" @click="edit(row)">{{can('products.'+props.kind,'operate')?'编辑':'查看'}}</el-button></template></el-table-column></el-table></template><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/><el-dialog :model-value="!!editing" :title="(kind==='declaration'?'报关资料':'清关资料')+' · '+(editing?.code||'')" width="min(1200px,95vw)" @close="editing=null"><el-form label-position="top" :disabled="!can('products.'+props.kind,'operate')||busy"><CustomsFields :model-value="form" :kind="kind"/></el-form><template #footer><el-button @click="editing=null">关闭</el-button><el-button v-if="can('products.'+props.kind,'operate')" type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.customs-tools{display:flex;gap:10px;align-items:center;padding:12px 0}.el-pagination{margin:14px 0}</style>
